def magic_square_test(my_matrix):
    """Return True if ``my_matrix`` is a magic square.

    A magic square is a non-empty square matrix in which the sums of
    every row, every column, and both main diagonals are all equal.
    Empty, non-square, and ragged inputs are not magic squares.
    """
    try:
        if not my_matrix:
            return False
        n = len(my_matrix)
        rows = [list(row) for row in my_matrix]
    except (TypeError, ValueError):
        return False

    if any(len(row) != n for row in rows):
        return False

    try:
        target = sum(rows[0])
        if any(sum(row) != target for row in rows):
            return False
        if any(
            sum(rows[i][j] for i in range(n)) != target for j in range(n)
        ):
            return False
        if sum(rows[i][i] for i in range(n)) != target:
            return False
        if sum(rows[i][n - 1 - i] for i in range(n)) != target:
            return False
    except TypeError:
        return False

    return True
